mapper.sql:
WHERE b.user_id = #{userId}
AND b.date >= #{start}
AND b.date <= #{end}
AND b.category_id = #{categoryId}
AND b.type = #{type}

mapper.select:
SELECT b.*, c.name AS category_name
FROM bill b JOIN category c ON b.category_id = c.id
WHERE b.id = #{id}

mapper.update:
UPDATE bill
amount = #{amount}, type = #{type}, category_id = #{categoryId}, date = #{date}, remark = #{remark},
WHERE id = #{id}
